// Execute the pinned original choreography; expected values are never generated by the C# port.
import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';import {pathToFileURL,fileURLToPath} from 'node:url';
const temp=path.resolve(process.argv[2]),root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),req=createRequire(path.join(temp,'package.json')),T=await import(pathToFileURL(req.resolve('three')));
const {KneelFall}=await import(pathToFileURL(path.join(temp,'src/client/body-collapse.js'))),{createCharacterRig}=await import(pathToFileURL(path.join(temp,'src/client/character-rig.js'))),{GIB_ROOTS}=await import(pathToFileURL(path.join(temp,'src/client/body-wounds.js')));
const cases=[];for(let c=0;c<8;c++){
 const rig=createCharacterRig('#70e1d0','#e5e7eb',true);rig.group.position.set(c%2*2,.865,0);const yaw=c*.39;rig.group.rotation.y=yaw;if(c>3){rig.head.rotation.x=-.12;rig.leftArm.rotation.z=.2;rig.rightLeg.rotation.x=.15;}rig.group.updateMatrixWorld(true);
 const roots=GIB_ROOTS.map(n=>rig.group.getObjectByName(n));const parts=roots.map(node=>{let parent=node.parent;while(parent&&!roots.includes(parent))parent=parent.parent;const p={name:node.name,parent:parent?.name,position:node.getWorldPosition(new T.Vector3()),quaternion:node.getWorldQuaternion(new T.Quaternion()),anchor:parent?parent.worldToLocal(node.getWorldPosition(new T.Vector3())):undefined,free:c===6&&node.name==='head',boxes:[]};
 const inverse=node.matrixWorld.clone().invert();node.traverse(m=>{if(!m.isMesh)return;let a=m.parent;while(a&&!roots.includes(a))a=a.parent;if(a!==node)return;const matrix=inverse.clone().multiply(m.matrixWorld),pos=new T.Vector3(),q=new T.Quaternion(),scale=new T.Vector3();matrix.decompose(pos,q,scale);let ankle=false;for(let n=m.parent;n&&n!==node;n=n.parent)if(n.name.endsWith('-ankle'))ankle=true;p.boxes.push({center:pos,quaternion:q,half:scale.multiplyScalar(.5),ankle});});
 if(node.name.endsWith('-knee')){const foot=node.getObjectByName(node.name.replace('-knee','-ankle'));p.ankle={pivot:node.worldToLocal(foot.getWorldPosition(new T.Vector3())),frame:node.getWorldQuaternion(new T.Quaternion()).invert().multiply(foot.getWorldQuaternion(new T.Quaternion()))};}return p;});
 const motion={kind:'kneel-fall',kneesAt:.32,releaseAt:.82,facing:yaw,velocity:{x:c%3*.7,y:0,z:c%2*1.2}},options={ground:0,shot:{x:c%2?.5:0,y:.1,z:c%2?1:-1},severity:.3+c*.1,props:c===7?[{pos:{x:1.9,y:.8,z:.3},size:{x:1,y:1.6,z:.4}}]:[]};
 const collapse=new KneelFall(parts,motion,options),samples=[];for(const age of [0,.015,.05,.15,.32,.47,.7,collapse.release]){const values=[];collapse.each(age,(name,p,linear,angular)=>values.push({name,position:p.position.toArray(),rotation:p.quaternion.toArray(),ankle:p.ankle?.toArray(),linear:linear.toArray(),angular:angular.toArray()}));samples.push({age,values});}
 cases.push({parts:parts.map(p=>({...p,position:p.position.toArray(),quaternion:p.quaternion.toArray(),anchor:p.anchor?.toArray(),boxes:p.boxes.map(b=>({...b,center:b.center.toArray(),half:b.half.toArray(),quaternion:b.quaternion.toArray()})),ankle:p.ankle?{pivot:p.ankle.pivot.toArray(),frame:p.ankle.frame.toArray()}:undefined})),motion,options,release:collapse.release,fall:collapse.fallAngle,samples});
}
fs.writeFileSync(path.join(root,'Tests/collapse-parity.json'),JSON.stringify({cases})+'\n');console.log('Exported',cases.length,'original collapses with pose/ankle/velocity samples');
